// BFS 模板：网格最短路径，visited 在 offer 时标记
int bfs(int[][] grid, int sr, int sc, int tr, int tc) {
    int m = grid.length, n = grid[0].length;
    Queue<int[]> q = new LinkedList<>();
    boolean[][] visited = new boolean[m][n];
    int[][] dirs = {{0,1},{0,-1},{1,0},{-1,0}};

    q.offer(new int[]{sr, sc});
    visited[sr][sc] = true;        // 入队时就标记，不是 poll 时
    int steps = 0;

    while (!q.isEmpty()) {
        int size = q.size();        // 当前层的节点数
        for (int i = 0; i < size; i++) {
            int[] cur = q.poll();
            if (cur[0] == tr && cur[1] == tc) return steps;  // 第一次到达即最短

            for (int[] d : dirs) {
                int nr = cur[0] + d[0], nc = cur[1] + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n
                    && !visited[nr][nc] && grid[nr][nc] == 1) {
                    visited[nr][nc] = true; // 入队前标记
                    q.offer(new int[]{nr, nc});
                }
            }
        }
        steps++;  // 遍历完一层，步数 +1
    }
    return -1; // 不可达
}

// 递归 DFS：连通块染色
void dfsRecursive(int[][] grid, int r, int c) {
    if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length
        || grid[r][c] == 0) return; // 递归基：越界或障碍
    grid[r][c] = 0; // 进入时标记，直接改原数组省空间
    dfsRecursive(grid, r + 1, c);
    dfsRecursive(grid, r - 1, c);
    dfsRecursive(grid, r, c + 1);
    dfsRecursive(grid, r, c - 1);
}

// 迭代 DFS：显式栈，避免递归栈溢出
void dfsIterative(int[][] grid, int sr, int sc) {
    int[][] dirs = {{0,1},{0,-1},{1,0},{-1,0}};
    Deque<int[]> stack = new ArrayDeque<>();
    stack.push(new int[]{sr, sc});
    grid[sr][sc] = 0; // push 时标记

    while (!stack.isEmpty()) {
        int[] cur = stack.pop();
        for (int[] d : dirs) {
            int nr = cur[0] + d[0], nc = cur[1] + d[1];
            if (nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length
                && grid[nr][nc] == 1) {
                grid[nr][nc] = 0; // push 时标记，不是 pop 时
                stack.push(new int[]{nr, nc});
            }
        }
    }
}

// 回溯 DFS：枚举所有路径（需要撤销 visited）
List<List<int[]>> allPaths = new ArrayList<>();
void dfsBacktrack(int[][] grid, int r, int c, int tr, int tc,
                  List<int[]> path, boolean[][] visited) {
    if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length
        || visited[r][c] || grid[r][c] == 0) return;
    if (r == tr && c == tc) {
        allPaths.add(new ArrayList<>(path)); // 到达终点，记录路径
        return;
    }
    visited[r][c] = true; // 进入时标记
    path.add(new int[]{r, c});
    int[][] dirs = {{0,1},{0,-1},{1,0},{-1,0}};
    for (int[] d : dirs) {
        dfsBacktrack(grid, r + d[0], c + d[1], tr, tc, path, visited);
    }
    path.remove(path.size() - 1); // 回溯：撤销路径
    visited[r][c] = false;        // 回溯：撤销标记，允许其他路径经过
}

// 双向 BFS：从起点和终点同时搜索，相遇时返回
// 适用于分支因子大、最短路径长的场景（如单词接龙）
int bidirectionalBFS(String begin, String end, Set<String> wordSet) {
    if (!wordSet.contains(end)) return 0;

    Set<String> front = new HashSet<>(); // 从起点出发的前线
    Set<String> back = new HashSet<>();  // 从终点出发的前线
    Set<String> visited = new HashSet<>();
    front.add(begin);
    back.add(end);
    visited.add(begin);
    visited.add(end);
    int steps = 1;

    while (!front.isEmpty() && !back.isEmpty()) {
        // 始终扩展较小的一侧，减少搜索空间
        if (front.size() > back.size()) {
            Set<String> temp = front;
            front = back;
            back = temp;
        }

        Set<String> next = new HashSet<>();
        for (String word : front) {
            char[] chars = word.toCharArray();
            for (int i = 0; i < chars.length; i++) {
                char original = chars[i];
                for (char ch = 'a'; ch <= 'z'; ch++) {
                    chars[i] = ch;
                    String newWord = new String(chars);
                    if (back.contains(newWord)) return steps + 1; // 相遇！
                    if (wordSet.contains(newWord) && visited.add(newWord)) {
                        next.add(newWord);
                    }
                }
                chars[i] = original;
            }
        }
        front = next;
        steps++;
    }
    return 0; // 不可达
}
